contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the contract. caller must send enough ETH to this test contract before calling.
    function checkPlayThenWin(uint256 ticketAmount, uint256 sendAmount) public {
        // Preconditions: sendAmount must equal the ticket price and match C.TICKET_AMOUNT
        // We cannot access C.TICKET_AMOUNT as a compile-time constant here; require caller supplies correct amount.
        require(sendAmount == ticketAmount, "mismatch amounts");
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // Make one play by paying the ticket amount to c.play().
        c.play{value: sendAmount}();

        // After a winning play (random==0) the contract P will transfer out pot and fee so its balance becomes 0.
        // We assert that c's current balance is zero. This holds for original C but is violated by the mutant
        // which only added FEE_AMOUNT to pot and would leave balance > 0 after payout.
        assert(address(c).balance == 0);
    }

    // Allow funding this test contract
    receive() external payable {}
}

