pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor address so the fuzzer can find an address that exercises difference
    // We fuzz a single parameter: address player. The ticket amount is fixed by contract (10).
    function testFuzz_property(address player) public {
        // admissible domain: non-zero address and not the contract itself
        vm.assume(player != address(0));
        vm.assume(player != address(this));
        vm.assume(player != address(c));

        uint256 ticket = 10; // matches C.TICKET_AMOUNT
        // fund the player so they can send the ticket
        vm.deal(player, ticket);

        // record pot before
        uint256 before = c.pot();

        // perform the call as the fuzzed player sending exactly the ticket amount
        vm.prank(player);
        c.play{value: ticket}();

        // After a successful play() call that sent exactly the ticket amount, the reference
        // contract must have increased pot by the full msg.value (ticket).
        // This single assertion reads c's public getter pot() and will hold for the reference
        // but the mutant (which adds only FEE_AMOUNT) will violate it for some player inputs
        // (the randomness path where pot is not zeroed by winning also exposes the difference).
        assertTrue(c.pot() == before + ticket);
    }
}

