pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: an address that will call play()
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be non-zero EOA-like address
        vm.assume(caller != address(0));

        // Ensure caller has ticket funds
        uint256 ticket = 10;
        vm.deal(caller, ticket);

        // record pot before
        uint256 before = c.pot();

        // Make the call from caller sending exactly TICKET_AMOUNT
        vm.prank(caller);
        // call play with the correct value; wrap in try/catch to prevent randomness-induced revert
        // (play only reverts if msg.value != TICKET_AMOUNT, so this should not revert)
        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted for some unexpected reason, exclude that run
        vm.assume(ok);

        // For the reference contract, if the play did NOT pay out a win (i.e., pot was not reset to 0),
        // pot must have increased by exactly the ticket amount.
        // We detect a non-winning play by observing that pot != 0 (because on win pot is set to 0).
        uint256 after = c.pot();

        // If the play resulted in a win, pot becomes 0 in reference; in that case the rule about
        // increment by ticket does not need to hold (since pot has been reset). We only assert
        // the increment property for non-winning outcomes: after != 0 implies after == before + ticket.
        assertTrue(after == 0 || after == before + ticket);
    }
}

