import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address; the difference depends on caller (affects pseudo-random result)
    function testFuzz_property(address caller) public {
        // admissible domain: caller must not be zero and must be a different address than the test contract
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // give caller the ticket amount
        uint ticket = 10; // matches C.TICKET_AMOUNT
        vm.deal(caller, ticket);

        // record old pot
        uint oldPot = c.pot();

        // have caller call play() with exactly the ticket amount
        vm.prank(caller);
        c.play{value: ticket}();

        // After a play() completes, the reference contract C guarantees:
        // either the caller won (pot reset to 0) or the pot increased by exactly TICKET_AMOUNT.
        // We assert that the resulting pot is either 0 or oldPot + TICKET_AMOUNT.
        // The mutant that only increments pot by FEE_AMOUNT will for some caller produce a pot
