contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call with the ticket payment amount and whether the random outcome equals 0 (win)
    // We cannot control randomness, so we observe post-state only when a win happened by checking
    // that pot is zero and balances moved. The rule asserts that when a play results in a win
    // (pot reset to 0 and contract balance decreased), the winner's received amount equals
    // previous pot + ticket - fee. We expose previous pot via c.pot() and fee via constant values from c are not public,
    // but FEE_AMOUNT is not accessible; instead we infer fee by using bank's balance change (bank gains FEE_AMOUNT).

    // The test takes as parameters the caller address (msg.sender) cannot be set; instead we accept
    // the payment amount and require it equals C.TICKET_AMOUNT by querying c.TICKET_AMOUNT().

    function check(uint ticketAmount) public payable {
        // ensure this contract has enough balance to pay ticket
        require(address(this).balance >= ticketAmount);

        // read constants from contract
        uint T = c.TICKET_AMOUNT();
        // require caller supplied correct ticket amount
        require(ticketAmount == T);

        // record balances and pot before the play
        uint pot_before = c.pot();
        uint bank_before = address(c.bank()).balance;
        uint self_before = address(this).balance;

        // perform the play sending the ticket amount
        c.play{value: ticketAmount}();

        // observe after-state
        uint pot_after = c.pot();
        uint bank_after = address(c.bank()).balance;
        uint self_after = address(this).balance;

        // determine if this play resulted in a win: in that case contract pot is reset to 0 and caller received payout
        bool win = (pot_after == 0) && (self_after > self_before - ticketAmount);

        // If it's a win, then bank gained exactly FEE_AMOUNT and the winner's net gain equals pot_before + ticket - FEE_AMOUNT.
        // We express that without naming FEE_AMOUNT by relating bank change to the payout difference.
        // payout_to_winner = self_after - (self_before - ticketAmount)
        // bank_gain = bank_after - bank_before
        // The invariant (on original) is: payout_to_winner == pot_before + ticketAmount - bank_gain

        uint payout_to_winner = 0;
        if (self_after > self_before - ticketAmount) {
            payout_to_winner = self_after - (self_before - ticketAmount);
        }
        uint bank_gain = bank_after - bank_before;

        // Final single assertion: if win then payout_to_winner == pot_before + ticketAmount - bank_gain
        assert(!win || payout_to_winner == pot_before + ticketAmount - bank_gain);
    }

    // allow receiving Ether to fund the test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        // require caller provides exactly the ticket amount to play
        require(amount == 10, "must pay ticket amount");
        require(address(this).balance >= amount, "insufficient balance to send");

        // call play with the provided ticket amount
        c.play{value: amount}();

        // observe pot via public getter: it should have increased by exactly the ticket amount (10)
        // Since starting pot could be arbitrary, we express the rule as pot is a multiple of 10 and specifically
        // that after one play the pot % 10 == 0 and pot/10 >= 1. This captures that pot increased by exactly one ticket
        // (in original contract pot increments by msg.value == 10). The mutant doubling would make pot increase by 20,
        // which still leaves pot % 10 == 0, so we must assert exact increment relative to amount: pot == amount + (pot - amount) impossible here.
        // Instead we read pot and assert that pot equals 10 (since test invokes exactly one play on a fresh contract state for which constructor sets pot=0).

        uint potAfter = c.pot();
        // For original contract, a fresh deployed contract has pot == 10 after one play; mutant results in 20.
        assert(potAfter == 10);
    }
    receive() external payable { }
}

